typedef struct LinkNode {
    char data;
    struct LinkNode *next;
} LinkNode;

// 计算数据结点个数
int Length(LinkNode *head) {
    int len = 0;
    LinkNode *p = head->next;  // 跳过头结点
    while (p != NULL) {
        len++;
        p = p->next;
    }
    return len;
}

// 查找共同后缀起始结点
LinkNode* FindCommonLinkList(LinkNode *str1, LinkNode *str2) {
    int len1 = Length(str1), len2 = Length(str2);
    LinkNode *p = str1, *q = str2;
    // 对齐：使p和q到尾的距离相等
    if (len1 > len2) {
        for (int i = 0; i < len1 - len2; i++)
            p = p->next;
    } else {
        for (int i = 0; i < len2 - len1; i++)
            q = q->next;
    }
    // 同步移动直到相遇
    while (p != NULL && q != NULL && p != q) {
        p = p->next;
        q = q->next;
    }
    return p;  // p即为共同起始结点（若无则为NULL）
}
